<template><section><div class="page-heading"><div><div class="eyebrow">ACCOUNTS</div><h1>用户管理</h1><p>只管理账号访问权限，不查看训练或聊天内容。</p></div></div>
  <div class="card"><form class="search-row" @submit.prevent="search"><el-input v-model="keyword" maxlength="100" placeholder="搜索用户名、昵称或邮箱" clearable/><el-button native-type="submit" type="primary" :loading="busy">搜索</el-button></form>
  <el-alert v-if="error" :title="error" type="error" :closable="false"/>
  <div class="mobile-record-list" v-loading="busy" aria-label="用户卡片"><MobileRecordCard v-for="user in users" :key="user.id" :title="user.nickname || user.username"><template #status><el-tag :type="user.status==='active'?'success':'info'">{{user.status==='active'?'正常':'停用'}}</el-tag></template><p>{{user.username}} · #{{user.id}}</p><p>{{user.email || '未填写邮箱'}}</p><p>角色：{{user.role==='admin'?'管理员':'跑者'}}</p><template #actions><el-button @click="edit(user)">管理权限</el-button></template></MobileRecordCard><el-empty v-if="!busy && !users.length" description="没有匹配的用户"/></div>
  <el-table class="desktop-record-table" :data="users" v-loading="busy"><el-table-column prop="id" label="ID" width="80"/><el-table-column prop="username" label="用户名" min-width="150"/><el-table-column prop="nickname" label="昵称" min-width="120"/><el-table-column prop="email" label="邮箱" min-width="210"/><el-table-column label="角色" width="120"><template #default="{row}">{{row.role==='admin'?'管理员':'跑者'}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='active'?'success':'info'">{{row.status==='active'?'正常':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="110"><template #default="{row}"><el-button text type="primary" @click="edit(row)">管理权限</el-button></template></el-table-column></el-table>
  <el-pagination layout="prev,pager,next,total" :total="total" :page-size="20" v-model:current-page="page" @current-change="load" :disabled="busy"/>
  </div>
  <el-dialog v-model="visible" title="调整账号访问权限" width="440px" :close-on-click-modal="false"><p>{{selected?.username}} · #{{selected?.id}}</p><el-alert title="停用会阻止该账号后续授权请求；授予管理员意味着可以管理其他账号和全局课表配置。" type="warning" :closable="false"/><el-form label-position="top"><el-form-item label="角色"><el-select v-model="role"><el-option label="跑者" value="user"/><el-option label="管理员" value="admin"/></el-select></el-form-item><el-form-item label="状态"><el-select v-model="status"><el-option label="正常" value="active"/><el-option label="停用" value="disabled"/></el-select></el-form-item></el-form><template #footer><el-button @click="visible=false" :disabled="saving">取消</el-button><el-button type="primary" :loading="saving" @click="save">确认变更</el-button></template></el-dialog>
</section></template>
<script setup lang="ts">
import {onMounted,ref} from 'vue';import {ElMessage} from 'element-plus';import {api,consoleApi,errorText} from './api';
import MobileRecordCard from '@/components/common/MobileRecordCard.vue';
interface User{id:number;username:string;nickname:string|null;email:string|null;role:string;status:string}
const users=ref<User[]>([]),keyword=ref(''),page=ref(1),total=ref(0),busy=ref(false),saving=ref(false),error=ref(''),visible=ref(false),selected=ref<User|null>(null),role=ref('user'),status=ref('active');
let generation=0;
async function load(){const attempt=++generation;busy.value=true;error.value='';try{const {data}=await api.get(consoleApi+'/users',{params:{keyword:keyword.value,page:page.value,page_size:20}});if(attempt===generation){users.value=data.items;total.value=data.total;}}catch(e){if(attempt===generation){users.value=[];error.value=errorText(e);}}finally{if(attempt===generation)busy.value=false;}}
function search(){page.value=1;load();}function edit(user:User){selected.value={...user};role.value=user.role;status.value=user.status;visible.value=true;}
async function save(){if(!selected.value||saving.value)return;saving.value=true;try{await api.patch(consoleApi+'/users/'+selected.value.id,{role:role.value,status:status.value,expected_role:selected.value.role,expected_status:selected.value.status});visible.value=false;ElMessage.success('权限已更新');await load();}catch(e){ElMessage.error(errorText(e));}finally{saving.value=false;}}onMounted(load);
</script>
